#[cfg(test)]
mod tests {
    #![allow(unused_imports)]
    use super::*;
    use crate::field::FieldValue;
    use crate::packet::Packet;

    // protogen:tests begin
    /// RFC 5880 §4.1 control packet: version 1, state Up (3), detect multiplier 3, length 24, discriminators 1 and 2.
    fn vector() -> Vec<u8> {
        vec![
            0x20, 0xc0, 0x03, 0x18, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x02, 0x00, 0x0f,
            0x42, 0x40, 0x00, 0x0f, 0x42, 0x40, 0x00, 0x00, 0x00, 0x00,
        ]
    }

    #[test]
    fn dissects_the_rfc_vector() {
        let p = Packet::dissect(vector(), ProtoId::Bfd);
        let l = p.find_layer(ProtoId::Bfd).unwrap();
        assert_eq!(p.get(l, "version").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "diag").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.get(l, "sta").unwrap(), FieldValue::Uint(3));
        assert_eq!(p.get(l, "detect_mult").unwrap(), FieldValue::Uint(3));
        assert_eq!(p.get(l, "len").unwrap(), FieldValue::Uint(24));
        assert_eq!(p.get(l, "my_discriminator").unwrap(), FieldValue::Uint(1));
        assert_eq!(p.get(l, "your_discriminator").unwrap(), FieldValue::Uint(2));
        assert_eq!(
            p.get(l, "min_tx_interval").unwrap(),
            FieldValue::Uint(1000000)
        );
        assert_eq!(
            p.get(l, "min_rx_interval").unwrap(),
            FieldValue::Uint(1000000)
        );
        assert_eq!(p.get(l, "echo_rx_interval").unwrap(), FieldValue::Uint(0));
        assert_eq!(p.raw_bytes(), &vector()[..]);
    }

    #[test]
    fn truncation_does_not_panic() {
        for n in 0..vector().len() {
            let p = Packet::dissect(vector()[..n].to_vec(), ProtoId::Bfd);
            assert_eq!(p.raw_bytes(), &vector()[..n]);
        }
    }

    #[test]
    fn writes_survive_a_rebuild() {
        let mut p = Packet::dissect(vector(), ProtoId::Bfd);
        let l = p.find_layer(ProtoId::Bfd).unwrap();
        let n = p.raw_bytes().len();
        for f in crate::proto::active_fields(ProtoId::Bfd, false, p.header(l))
            .filter(|f| f.kind == crate::field::FieldKind::Uint && f.bit_len <= 32)
            .map(|f| f.name)
            .collect::<Vec<_>>()
        {
            p.set_uint(l, f, 1);
        }
        assert_eq!(p.to_bytes().len(), n);
    }
    // protogen:tests end
}
